if (typeof window !== "undefined") {
  window.addEventListener("wheel", (e) => {
    if (!window.matchMedia("(min-width: 1024px)").matches) return;
    const track = document.querySelector("[data-bend-scroll]");
    if (!track) return;
    const card = document.querySelector(".experience-about-card-wrap--desktop") || document.querySelector(".about-me-card");
    const targetScroll = card ? Math.round(card.offsetLeft - (window.innerWidth - card.offsetWidth) / 2) : (track.scrollWidth - track.clientWidth);
    if (targetScroll <= 1) return;
    const curY = window.scrollY || (window.lenis ? window.lenis.scroll : 0);
    const delta = Math.abs(e.deltaX) > Math.abs(e.deltaY) ? e.deltaX : e.deltaY;
    if (delta === 0) return;
    if (delta > 0) {
      if (track.scrollLeft < targetScroll - 2) {
        e.preventDefault();
        e.stopImmediatePropagation();
        track.scrollLeft = Math.min(track.scrollLeft + delta, targetScroll);
        return;
      }
    }
    if (delta < 0) {
      if (curY > 1) return;
      if (track.scrollLeft > 1) {
        e.preventDefault();
        e.stopImmediatePropagation();
        track.scrollLeft = Math.max(track.scrollLeft + delta, 0);
        return;
      }
    }
  }, { capture: true, passive: false });
}


